# ORIGINAL: CONT1's run-time rows for reset/3, shift/1, shift_for_copy/1 and call_continuation/1 (audit D-0402 item 2d); the rows are this file's own, generated by evidence/CONT1/gen_cr_rows.py
# test/core_lang/test_cont_run_swipl.jl — the RUN side of the continuation instructions (pl-vmi.c I_RESET :5754, I_EXITRESET :5801,
# I_CALLCONT :5839, I_SHIFT :5874, I_SHIFTCP :5908, I_YIELD :2410; pl-cont.c shift :372, put_environment :110, push_continuation :456;
# pl-gc.c mark_active_environment :1866) through the booted system's reset/3, shift/1, shift_for_copy/1, call_continuation/1 and
# '$engine_yield'/2 (boot/init.pl:604-645, boot/engines.pl:152):
#   * A PROGRAM consulted by the kernel's loader and cases `t_<id>(R)`, each wrapped in `catch(Goal, error(SsuE, _), R = raised(SsuE))`;
#     every row runs IN ORDER in one database. A continuation is never printed whole (its `$cont$` terms carry a clause blob and
#     stack positions): the rows print B, whether C == 0, the length of the call_continuation list, the slots, the context module.
#   * Every swipl answer line is PINNED (swipl 10.1.19, this program and driver, LC_ALL=C, 2026-11-04, two runs byte-identical;
#     evidence/CONT1/cr_rows.out); with `swipl` on PATH the live answers are compared with the pins too.
#   * t_r_y, t_r_y_meta, t_r_sb, t_r_hold, t_r_hold_cl, t_r_ssu, t_r_ssu_l, t_r_ssu_meta (and the program's cr_id/cr_y/cr_sb/cr_hold/cr_s/cr_ssu*) were added 2026-11-05 for the CONT1 engine fix (audit D-0424),
#     pinned from swipl 10.1.19 with the same driver (two runs byte-identical); the pool check `_cr_pools_live` runs at every answer.
#   * UNVERIFIED on the kernel: gate decides (a mismatch is traced to its upstream cause, not re-pinned).
using Test, LogicKernel
const LK = LogicKernel

# TERM TYPES PER CHUNK: REFERENCE — the continuations' run side (src/pl-cont.jl, src/pl-gc.jl, src/pl-wam.jl I_RESET .. I_YIELD); every type in CI
include(joinpath(@__DIR__, "..", "term_under_test.jl"))
const _CR = lk_term_type(Union{Int64, Float64, String, BigInt, Rational{BigInt}})
_crs(x) = lk_sym(_CR, Symbol(x))

"A term as the driver's `enc/1` writes it: `V<i>` by first occurrence, atoms by name, compounds `name(args)`."
function _cr_enc(t::_CR, seen::Vector{UInt64}=UInt64[])::String
    k = kind(t)
    if k === VAR
        i = findfirst(==(var_key(t)), seen)
        if i === nothing
            push!(seen, var_key(t))
            i = length(seen)
        end
        return "V$(i - 1)"
    elseif k === SYM
        return if is_nil(t)
            "[]"
        elseif is_blob(t)
            "<blob>"
        else
            sym_text(t)
        end   # a clause blob (a continuation's `$cont$`): a row says so, it does not raise
    elseif k === GND
        v = lk_value(t)
        v isa AbstractString && return "s\"" * String(v) * "\""
        v isa Integer && return "$v"
        v isa AbstractFloat && return "$v"
        return "?$(typeof(v))"
    end
    h = child(t, 1)
    return (is_nil(h) ? "[]" : sym_text(h)) * "(" *
           join([_cr_enc(child(t, i), seen) for i in 2:nchildren(t)], ",") * ")"
end

# the swipl side: the MOD3b driver (consult, then every answer of each t_<id>/1, `enc`oded)
const _CR_DRIVER = raw"""
enc(T) :- enc(T, [], _).
enc(V, S0, S) :- var(V), !, ( vidx(S0, V, 0, I) -> S = S0 ; length(S0, I), append(S0, [V], S) ), format("V~w", [I]).
enc(T, S, S) :- T == [], !, write('[]').
enc(T, S, S) :- atom(T), !, write(T).
enc(T, S, S) :- string(T), !, format("s\"~w\"", [T]).
enc(T, S, S) :- integer(T), !, format("~w", [T]).
enc(T, S, S) :- float(T), !, format("~w", [T]).
enc(T, S0, S) :- compound_name_arity(T, N, A),
    write(N), format("(", []), encargs(1, A, T, S0, S), write(')').
encargs(I, A, _, S, S) :- I > A, !.
encargs(I, A, T, S0, S) :- arg(I, T, X), enc(X, S0, S1), ( I < A -> write(',') ; true ),
    I1 is I+1, encargs(I1, A, T, S1, S).
vidx([X|_], V, I, I) :- X == V, !.
vidx([_|Xs], V, I0, I) :- I1 is I0+1, vidx(Xs, V, I1, I).
fz_pred(N) :-
    format("~w", [N]), functor(G, N, 1),
    catch(findnsols(50, G, G, Gs), _, Gs = [exception]),
    forall(member(S, Gs), ( S == exception -> write(' exception') ; write(' '), enc(S) )), nl.
fz_run(File, Ns) :-
    catch(( consult(File), S = ok ), E, S = exc(E)),
    ( S == ok -> writeln(ok) ; S = exc(B), write('exc '), enc(B), nl ),
    forall(member(N, Ns), fz_pred(N)).
"""
function _cr_swipl_lines(path::String, names::Vector{String})::Vector{String}
    out = mktempdir() do d
        f = joinpath(d, "drv.pl")
        write(
            f,
            _CR_DRIVER * ":- initialization((fz_run('$path', [" * join(names, ",") *
            "]), halt)).\n"
        )
        read(
            pipeline(addenv(`swipl -q $f`, "LC_ALL" => "C"); stdin=devnull, stderr=devnull),
            String
        )
    end
    return String.(split(chomp(out), '\n'; keepempty=false))
end


# the program: the user predicates the rows run (iterator, effect handler, copied continuations, choice slots, liveness)
const _CR_PROGRAM = raw"""
cr_mem(a).
cr_mem(b).
cr_mem(c).
cr_gen(N, M) :- N =< M, shift(yield(N)), N1 is N+1, cr_gen(N1, M).
cr_gen(N, M) :- N > M.
cr_sum(Goal, Acc, Sum) :-
    reset(Goal, Ball, Cont),
    (   Cont == 0
    ->  Sum = Acc
    ;   Ball = yield(X), Acc1 is Acc+X, cr_sum(Cont, Acc1, Sum)
    ).
cr_run(Goal, S0, S) :-
    reset(Goal, Eff, Cont),
    (   Cont == 0
    ->  S = S0
    ;   Eff = put(V)
    ->  cr_run(Cont, V, S)
    ;   Eff = get(V)
    ->  V = S0, cr_run(Cont, S0, S)
    ).
cr_incr :- shift(get(V)), V1 is V+1, shift(put(V1)).
cr_prog :- cr_incr, cr_incr, cr_incr.
cr_fc(X) :- shift_for_copy(b), X = r.
cr_sh(X) :- shift(b), X = r.
cr_ite(X) :- ( shift(c), cr_mem(Y), Y == b -> X = Y ; X = none ).
cr_deep(0) :- shift(x).
cr_deep(N) :- N > 0, N1 is N-1, cr_deep(N1), cr_nop.
cr_lco(0) :- shift(x).
cr_lco(N) :- N > 0, N1 is N-1, cr_lco(N1).
cr_nop.
cr_live(X, Y, Z) :- W = 1, Y = f(X, W), shift(a), Z = g(Y).
cr_tr(M) :- shift(a), context_module(M).
:- module_transparent cr_tr/1.
cr_ctx(M) :- reset(cr_m:cr_tr(M), _, C), call(C).
cr_slots(G, S) :- reset(G, _, call_continuation([T|_])), T =.. [_, _, _, _|S].
cr_sha(T2) :- reset(cr_sh(_), _, call_continuation([T])), T =.. L, append(L0, [_], L), T2 =.. L0.
cr_not :- \+ ( shift(n), fail ), true.
cr_or(X) :- ( shift(o1), X = 1 ; X = 2 ).
cr_soft(X) :- ( shift(s1), cr_mem(Y), Y == b *-> X = Y ; X = none ).
cr_cutdeep(X) :- cr_mem(X), shift(c1), !.
cr_if2(X) :- ( cr_mem(Y), shift(i1), Y == b -> X = Y ; X = none ).
cr_late(X, Y) :- shift(l1), Y = f(X).
cr_fc_ite(X) :- ( shift_for_copy(f), cr_mem(Y), Y == b -> X = Y ; X = none ).
cr_id(X, X).
cr_y(R) :- reset(cr_ite(X), _, C), call(C), cr_id(X, R).
cr_sb(R) :- reset(cr_ite(X), _, C), call(C), X == zz, R = X.
cr_sb(second).
cr_hold(R) :- reset(cr_ite(X), _, C), call(C), cr_id(X, R), cr_mem(_), true.
cr_s(a, R) => R = no.
cr_s(b, R) => R = ok.
cr_ssu_ite(X) => ( shift(c), cr_mem(Y), Y == b -> X = Y ; X = none ).
cr_ssu(R) :- reset(cr_ssu_ite(X), _, C), call(C), cr_s(X, R0), R = R0.
cr_ssu_l(R) :- reset(cr_ssu_ite(X), _, C), call(C), cr_s(X, R).
"""

