"The program and cases as one file; the case predicates' names."
function _cr_file()::Tuple{String, Vector{String}}
    names = ["t_$(id)" for (id, _) in _CR_CASES]
    text =
        _CR_PROGRAM * join([
            "t_$(id)(R) :- catch(($g), error(SsuE, _), R = raised(SsuE)).\n" for
            (id, g) in _CR_CASES
        ])
    f = joinpath(mktempdir(), "contrun.pl")
    write(f, text)
    return f, names
end

"""
At an answer: the record pools hold the LIVE records — the choice points on the `BFR` chain and the frames
on the parent chains of the current frame and of those choice points' frames (rules_common.jl
`_rpools_live`) — plus records off those chains that lie below `lTop` and are marked dead: choice points
`unlinked` (`C_SOFTCUT`, or `c_cut` in a continuation's frame) and frames killed (`LK.isFrame` false, `c_cut`'s
`killFrame`); nothing else (src/pl-wam.jl, THE POOLS' INVARIANT; audit D-0424). A live record marked dead, or
a dead record not marked, is a reason string; `nothing` when the pools hold.
"""
function _cr_pools_live(ld::LK.PL_local_data{_CR})::Union{Nothing, String}
    chain = Set{Int}()
    c = ld.BFR
    while c != 0
        c <= ld.nchoices || return "BFR chain choice $c above nchoices=$(ld.nchoices)"
        ld.choices[c].unlinked && return "choice $c on the BFR chain is unlinked"
        push!(chain, c)
        c = ld.choices[c].parent
    end
    for i in 1:(ld.nchoices)
        i in chain && continue
        (ld.choices[i].unlinked && ld.choices[i].base < ld.lTop) ||
            return "choice $i off the chain (base $(ld.choices[i].base), lTop $(ld.lTop)) not unlinked below lTop"
    end
    fr = Set{Int}()
    for f0 in [[ld.choices[c].frame for c in chain]; ld.environment_frame]
        f = f0
        while f != 0 && !(f in fr)
            f <= ld.nframes || return "live frame $f above nframes=$(ld.nframes)"
            LK.isFrame(ld.frames[f]) || return "live frame $f is killed"
            push!(fr, f)
            f = ld.frames[f].parent
        end
    end
    for i in 1:(ld.nframes)
        i in fr && continue
        (!LK.isFrame(ld.frames[i]) && ld.frames[i].base < ld.lTop) ||
            return "frame $i off every live chain (base $(ld.frames[i].base), lTop $(ld.lTop)) not killed below lTop"
    end
    return nothing
end

"""
The kernel's lines for `names` after consulting `path`, as the driver writes swipl's; a run that
raises the refusal exception (`LK.NotPortedError`, its `what` and `step`) writes `refused <what> <step>`.
With `pools`, every answer's `_cr_pools_live` failure and every row that does not leave `nchoices`,
`nframes`, `lTop` and `BFR` as it found them is pushed there as `<name>: <reason>`.
"""
function _cr_kernel(path::String, names::Vector{String}; pools::Vector{String}=String[])
    gd = LK.PL_global_data{_CR}()
    ld = LK.PL_local_data{_CR}(gd)
    st, ball = LK.load_file!(gd, ld, path)
    out = [st === :ok ? "ok" : "exc " * _cr_enc(ball::_CR)]
    for name in names
        proc = LK.isCurrentProcedure(sym_key(_crs(name)), 1, LK.MODULE_user(gd))
        if proc === nothing || !LK.isDefinedProcedure(gd, proc)
            push!(out, "$name undefined")
            continue
        end
        sols = String[]
        before = (ld.nchoices, ld.nframes, ld.lTop, ld.BFR)
        fid = LK.PL_open_foreign_frame(ld)
        a = LK.PL_new_term_refs(ld, 1)
        LK.putSlotValue!(ld, a + 1, mk_var(_CR, LK.fresh_var_keys!(1)), LK.PutVarMap())
        qid = LK.PL_open_query(
            gd, ld, nothing, LK.PL_Q_CATCH_EXCEPTION | LK.PL_Q_EXT_STATUS, proc, a
        )
        n = 0
        refused = nothing
        while (n += 1) <= 50
            rc = try
                LK.PL_next_solution(gd, ld, qid)
            catch e
                e isa LK.NotPortedError || rethrow()
                refused = "refused " * e.what * " " * e.step
                break
            end
            if rc == LK.PL_S_TRUE || rc == LK.PL_S_LAST
                why = _cr_pools_live(ld)
                why === nothing || push!(pools, "$name: answer $n: $why")
                push!(
                    sols,
                    _cr_enc(mk_expr(_CR, _CR[_crs(name), lk_answers(ld, (a:a)...)...]))
                )
                rc == LK.PL_S_LAST && break
            elseif rc == LK.PL_S_EXCEPTION
                push!(sols, "exception")
                break
            else
                break
            end
        end
        if refused !== nothing                  # the run loop was left: the database is not reused
            push!(out, "$name " * refused)
            return out
        end
        LK.PL_close_query(ld, qid)
        LK.PL_close_foreign_frame(ld, fid)
        after = (ld.nchoices, ld.nframes, ld.lTop, ld.BFR)
        after == before ||
            push!(pools, "$name: (nchoices, nframes, lTop, BFR) $before -> $after")
        push!(out, "$name" * join(" " .* sols))
    end
    return out
end

# ── lTop after shift/1 and reset/3 (audit D-0403 item 4; LK-only white-box rows, pinned from swipl 10.1.19) ──
# What is compared: `statistics(localused, U)` is `8 * ld.lTop` (src/pl-prims.jl `_used_stack`, as test_at_body_swipl.jl reads it), taken
# twice inside ONE clause body: U0 inside the shifting clause (`cl_sh`, at the I_SHIFT instruction's frame) and handed out as the ball,
# U1 in the CALLER after `reset/3` returned. Upstream's `shift` trims lTop and `PL_close_foreign_frame` sets it back to the foreign frame
# opened at `lTop` (pl-cont.c:407/:411; pl-vmi.c:5889, :5891; pl-wam.c:327, :349), so the net lTop of `I_SHIFT` is the value before it:
# U1 == U0 (`same`), also for `shift_for_copy/1`. `t_lt_none` (reset/3 with no shift) leaves lTop as it was before the call (`same`).
# `t_lt_call` measures U0 BEFORE `reset/3` instead: the dead frames' words stay on the stack, so the answer is `above`: the rows do not
# all say `same`. A mutant that skips the raise before the close (CONT1-V3), or drops lTop to the caller's own, changes `same` to an
# error or `below`/`above`. Not vacuous: U0 is bound ONLY by a shift (the ball `ltop(U0)`); with no shift `D is U1-U0` raises and the row
# reads `exception`, which differs from the pin. Both sides are one extractor (`_cr_enc`) over the same file. The first `reset(cl_sh, ..)`
# of each row is a warm-up: swipl's first shift grows its local stack, which moves lBase and makes the first measurement differ.
const _CR_LT_PROGRAM = raw"""
cl_sh :- statistics(localused, U), shift(ltop(U)).
cl_sc :- statistics(localused, U), shift_for_copy(ltop(U)).
cl_cmp(U0, U1, R) :- D is U1-U0, ( D =:= 0 -> R = same ; D > 0 -> R = above ; R = below ).
cl_kind(C, K) :- ( C == 0 -> K = plain ; K = shifted ).
t_lt_shift(R) :- reset(cl_sh, _, _), reset(cl_sh, ltop(U0), _), statistics(localused, U1), cl_cmp(U0, U1, R).
t_lt_copy(R) :- reset(cl_sc, _, _), reset(cl_sc, ltop(U0), _), statistics(localused, U1), cl_cmp(U0, U1, R).
t_lt_none(R) :- statistics(localused, U0), reset(true, _, _), statistics(localused, U1), cl_cmp(U0, U1, R).
t_lt_call(R) :- reset(cl_sh, _, _), statistics(localused, U0), reset(cl_sh, _, _), statistics(localused, U1), cl_cmp(U0, U1, R).
t_lt_cont(R) :- reset(cl_sh, _, _), reset(cl_sh, ltop(U0), C), statistics(localused, U1), cl_cmp(U0, U1, R0), cl_kind(C, K), R = R0-K.
"""
const _CR_LT_NAMES = ["t_lt_shift", "t_lt_copy", "t_lt_none", "t_lt_call", "t_lt_cont"]
const _CR_LT_PINNED = [
    raw"ok",
    raw"t_lt_shift t_lt_shift(same)",
    raw"t_lt_copy t_lt_copy(same)",
    raw"t_lt_none t_lt_none(same)",
    raw"t_lt_call t_lt_call(above)",
    raw"t_lt_cont t_lt_cont(-(same,shifted))"
]
function _cr_lt_file()::Tuple{String, Vector{String}}
    f = joinpath(mktempdir(), "contlt.pl")
    write(f, _CR_LT_PROGRAM)
    return f, _CR_LT_NAMES
end

@testset "lTop after shift/reset equals the value before the call (CONT1, white-box)" begin
    f, names = _cr_lt_file()
    pools = String[]
    kl = _cr_kernel(f, names; pools=pools)
    @test length(kl) == length(_CR_LT_NAMES) + 1
    for l in pools
        println(stderr, "  pools ", l)
    end
    @test isempty(pools)                        # the pools after every answer and every row (audit D-0424)
    for (k, p) in zip(kl, _CR_LT_PINNED)
        k == p || println(stderr, "  ours  ", k, "\n  swipl ", p)
        @test k == p
    end
    # not vacuous: both sides answer every row (a pin per name plus "ok"), the answers are not all `same` (t_lt_call), and the shifted
    # rows answer `same` with the continuation non-empty (t_lt_cont)
    @test length(_CR_LT_PINNED) == length(_CR_LT_NAMES) + 1
    @test all(l -> startswith(l, "t_lt_") || l == "ok", _CR_LT_PINNED)
    @test count(l -> occursin("(same)", l) || occursin("same,shifted", l), _CR_LT_PINNED) >=
        4
    @test any(l -> occursin("(above)", l), _CR_LT_PINNED)
    @test raw"t_lt_cont t_lt_cont(-(same,shifted))" in _CR_LT_PINNED
    @test !any(l -> occursin("exception", l) || occursin("refused", l), kl)
end

@testset "reset/3, shift/1, call_continuation/1 run as swipl's (CONT1)" begin
    f, names = _cr_file()
    pools = String[]
    kl = _cr_kernel(f, names; pools=pools)
    @test length(kl) == length(_CR_CASES) + 1
    for (k, p) in zip(kl, _CR_PINNED)
        k == p || println(stderr, "  ours  ", k, "\n  swipl ", p)
        @test k == p
    end
    # not vacuous: both sides answer every case, through one extractor (_cr_enc); the rows answer the error terms,
    # the iterator and effect-handler results, the twice-resumed lists and the continuation shapes
    @test length(_CR_PINNED) == length(_CR_CASES) + 1
    @test all(l -> startswith(l, "t_") || l == "ok", _CR_PINNED)
    @test count(l -> occursin("raised(existence_error(reset,", l), _CR_PINNED) >= 2
    @test count(l -> occursin("raised(", l), _CR_PINNED) >= 6
    @test raw"t_r_iter t_r_iter(15)" in _CR_PINNED
    @test raw"t_r_effect t_r_effect(3)" in _CR_PINNED
    @test raw"t_r_twice t_r_twice([|](r,[|](r,[])))" in _CR_PINNED
    @test raw"t_r_ite_cut t_r_ite_cut([|](b,[]))" in _CR_PINNED
    # the pools after every answer and every row (audit D-0424): a cut in a continuation's frame (t_r_ite_once, t_r_y,
    # t_r_y_meta, t_r_sb) leaves its records below lTop marked dead, and the last call (I_DEPART: t_r_ite_once and t_r_y_meta
    # under catch/3's meta-call; L_NOLCO: t_r_y's compiled clause) or the clause choice point resumed in place (t_r_sb)
    # reclaims them (src/pl-wam.jl `dropDeadRecords!`). Not vacuous: the four rows answer (their pins are in the list)
    # t_r_hold, t_r_hold_cl: NO last call after the cut and a choice point left (`cr_mem(_), true`: lTop cannot fall past the dead
    # records), so they stay in the pools up to every answer and `_cr_pools_live` alone sees them (not the LCO assertions): without c_cut's marks it says 'not unlinked below lTop'
    # / 'not killed below lTop'.
    for l in pools
        println(stderr, "  pools ", l)
    end
    @test isempty(pools)
    @test raw"t_r_y t_r_y(b)" in _CR_PINNED
    @test raw"t_r_sb t_r_sb(second)" in _CR_PINNED
    @test raw"t_r_hold t_r_hold(b) t_r_hold(b) t_r_hold(b)" in _CR_PINNED
    @test raw"t_r_hold_cl t_r_hold_cl(b) t_r_hold_cl(b) t_r_hold_cl(b)" in _CR_PINNED
    # t_r_ssu, t_r_ssu_l, t_r_ssu_meta: an SSU clause (`=>`, I_CHP .. I_SSU_COMMIT) called after the cut in a continuation's
    # frame, as a non-last, a last (I_DEPART) and a meta-called last goal: I_SSU_COMMIT's `_no_record_above` assertion holds
    # (the dead records lie BELOW the new frame, or are reclaimed by I_DEPART's slow path first; D-0424 follow-up probe)
    @test raw"t_r_ssu t_r_ssu(ok)" in _CR_PINNED
    @test raw"t_r_ssu_l t_r_ssu_l(ok)" in _CR_PINNED
    @test raw"t_r_ssu_meta t_r_ssu_meta(ok)" in _CR_PINNED
    @test any(l -> startswith(l, "t_r_slots ") && occursin("<inactive>", l), _CR_PINNED)
    @test any(
        l ->
            startswith(l, "t_r_yield_out ") &&
            occursin("permission_error(execute,vmi,I_YIELD)", l),
        _CR_PINNED
    )
end

@testset "the pins are swipl's (live, when swipl is on PATH)" begin
    swipl = get(ENV, "LOGICKERNEL_NO_SWIPL", "") == "1" ? nothing : Sys.which("swipl")
    # the pinned table is the driver's whole output (the inert-testset guard: an assertion either way)
    @test length(_CR_PINNED) == length(_CR_CASES) + 1
    if swipl === nothing
        @info "CONT1 RUN ROWS LIVE CHECK NOT RUN: `swipl` is not on PATH here. It runs in tools/run_tests.sh and CI."
    else
        f, names = _cr_file()
        @test _cr_swipl_lines(f, names) == _CR_PINNED
        f2, names2 = _cr_lt_file()
        @test _cr_swipl_lines(f2, names2) == _CR_LT_PINNED
    end
end
